SELECT FROM work_order
AND is_deleted = 0
AND applicant_id = #{applicantId}
AND status = #{status}
AND order_type = #{orderType}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR order_no LIKE CONCAT('%', #{keyword}, '%') OR applicant_name LIKE CONCAT('%', #{keyword}, '%'))
AND department_id = #{departmentId}
ORDER BY create_time ASC ORDER BY create_time DESC ORDER BY update_time ASC ORDER BY update_time DESC ORDER BY submit_time ASC ORDER BY submit_time DESC ORDER BY priority ASC ORDER BY priority DESC ORDER BY status ASC ORDER BY status DESC ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM work_order

    AND is_deleted = 0

        AND applicant_id = #{applicantId}


        AND status = #{status}


        AND order_type = #{orderType}


        AND (title LIKE CONCAT('%', #{keyword}, '%')
             OR order_no LIKE CONCAT('%', #{keyword}, '%')
             OR applicant_name LIKE CONCAT('%', #{keyword}, '%'))


        AND department_id = #{departmentId}

